package com.teeniv.whatsapp;
import android.view.*;import android.widget.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.bumptech.glide.Glide;import java.util.*;
public class UserAdapter extends RecyclerView.Adapter<UserAdapter.Holder>{interface OnUserClick{void click(User u);}ArrayList<User> source,shown;OnUserClick callback;UserAdapter(ArrayList<User> data,OnUserClick cb){source=data;shown=new ArrayList<>(data);callback=cb;}void filter(String q){shown.clear();for(User u:source)if(((u.name==null?"":u.name)+" "+(u.email==null?"":u.email)).toLowerCase().contains(q.toLowerCase()))shown.add(u);notifyDataSetChanged();}public int getItemCount(){return shown.size();}@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.row_user,p,false));}public void onBindViewHolder(@NonNull Holder h,int i){User u=shown.get(i);h.name.setText(u.name==null?"Chat user":u.name);h.email.setText(u.email==null?"Tap to start a conversation":u.email);if(u.photoUrl!=null&&!u.photoUrl.isEmpty())Glide.with(h.avatar).load(u.photoUrl).circleCrop().into(h.avatar);else h.avatar.setImageResource(R.drawable.avatar_bg);h.itemView.setOnClickListener(v->callback.click(u));}static class Holder extends RecyclerView.ViewHolder{TextView name,email;ImageView avatar;Holder(View v){super(v);name=v.findViewById(R.id.userName);email=v.findViewById(R.id.userEmail);avatar=v.findViewById(R.id.avatar);}}}
